window.kbPageData["views/entry/k-8b937d0610a6cb2f"] = {"key":"entry/k-8b937d0610a6cb2f","state":{"route":"entry/k-8b937d0610a6cb2f"},"node":{"id":"k-8b937d0610a6cb2f","mode":"k","title":"预期目标","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"（一）预期目标\n今年发展主要预期目标是：经济增长 4.5%－5%①，在实际工作中努力争取更好结果；城\n镇调查失业率 5.5%左右，城镇新增就业 1200 万人以上；居民消费价格涨幅 2%左右；居民\n收入增长和经济增长同步；国际收支基本平衡；粮食产量 1.4 万亿斤左右；单位国内生产\n总值二氧化碳排放…","sources":[{"id":"79f1d712beb5a242","label":"预期目标","topic":"年度政府工作","category":"时政","text":"（一）预期目标\n今年发展主要预期目标是：经济增长 4.5%－5%①，在实际工作中努力争取更好结果；城\n镇调查失业率 5.5%左右，城镇新增就业 1200 万人以上；居民消费价格涨幅 2%左右；居民\n收入增长和经济增长同步；国际收支基本平衡；粮食产量 1.4 万亿斤左右；单位国内生产\n总值二氧化碳排放降低 3.8%左右。\n提出这些预期目标，主要考虑是开局之年为调结构、防风险、促改革留出空间，为后期\n更好发展打牢基础。经济增长目标同 2035 年远景目标总体衔接，与我国经济长期增长潜力\n基本吻合，实现这个目标具备有利条件，各地区要结合实际，通过扎实工作争取好的结果。\n城镇调查失业率 5.5%左右，体现了在就业总量和结构性压力较大的情况下，坚持就业优先\n政策导向和加大稳就业力度的要求。居民消费价格涨幅 2%左右，考虑了预期引导和现实可\n能，我们将通过改善总供求关系，推动价格总水平由负转正、消费价格合理温和回升，促进\n经济良性循环。单位国内生产总值二氧化碳排放降低 3.8%左右②，综合考虑了经济社会发展、\n绿色低碳转型和国家能源安全等多种需要，有利于有序实现 2030 年前碳达峰目标。","source":{"doc":"6cbfb01fe723bba64b75","first":21,"last":22,"page":21,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-8b937d0610a6cb2f":[]}};
